// Extraire le job_id des query params
const input = $input.first().json;

const jobId = input.query?.job_id || input.params?.job_id || '';

if (!jobId) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: 'Le paramètre "job_id" est requis',
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    jobId: jobId
  }
}];

// Formater la réponse
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || data.message || data.detail || 'Job non trouvé',
        status: 'JOB_NOT_FOUND'
      }
    }
  }];
}

// Calculer la progression
const totalVerses = data.verses_count || data.metadata?.verses_count || 0;
const translationsSaved = data.translations_saved || 0;
const progressPercent = totalVerses > 0 ? Math.round((translationsSaved / totalVerses) * 1000) / 10 : 0;

return [{
  json: {
    success: true,
    job_id: data.job_id || prevData.jobId,
    status: data.status || 'unknown',
    job_type: data.job_type,
    text_name: data.text_name || data.metadata?.text_name,
    chapter: data.chapter || data.metadata?.chapter,
    current_verse: data.current_verse,
    total_verses: totalVerses,
    translations_saved: translationsSaved,
    progress_percent: progressPercent,
    tokens: data.tokens,
    error: data.error,
    created_at: data.created_at,
    updated_at: data.updated_at
  }
}];
